<?php require_once __DIR__.'/db.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([$id]);$p=$s->fetch();if(!$p)die('Product not found.');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Product</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="wrap"><div class="card"><h2>Edit Product</h2><form method="post" action="product_action.php" class="grid"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$p['id']?>"><div><label>Product Name</label><input name="name" value="<?=e($p['name'])?>" required></div><div><label>Price (₹)</label><input name="price" type="number" step=".01" min="0" value="<?=$p['price']?>" required></div><div><label>Stock Quantity</label><input name="stock_quantity" type="number" min="0" value="<?=$p['stock_quantity']?>" required></div><div><label>Low Stock Alert At</label><input name="low_stock_threshold" type="number" min="0" value="<?=$p['low_stock_threshold']?>" required></div><div class="actions"><button class="btn primary">Save Changes</button><a class="btn light" href="index.php#products">Cancel</a></div></form></div></main></body></html>
